mapper.select:
SELECT c.id, c.user_id userId, u.actual_name userName, c.file_md5 fileMd5, c.file_name fileName, c.file_url fileUrl, c.file_size fileSize, c.file_path filePath, c.is_dir isDir, c.create_time uploadTime, c.is_valid isValid, c.extend_name extendName, c.storage_type storageType, f.id labelId, f.label_name labelName FROM t_wp_user_file c, t_wp_user_file_label ufl, t_base_user u,t_wp_file_label f WHERE u.id = c.user_id and c.id = ufl.file_id and f.id = ufl.label_id and u.is_valid =1 and c.is_valid =1 and f.is_valid =1 and ufl.is_valid = 1 and f.id = #{query.labelId}
AND (u.actual_name like #{likeName} or c.file_name like #{likeName})
order BY c.create_time desc

SELECT fl.id id, fl.label_name labelName,
count(uf.id) count FROM t_wp_file_label fl left join t_wp_user_file_label ufl on ufl.label_id = fl.id and ufl.is_valid = 1 left join t_wp_user_file uf on uf.id = ufl.file_id and uf.is_valid = 1 left join t_base_user u on u.id = fl.user_id WHERE fl.is_valid = 1 and u.is_valid = 1
and fl.user_id = #{userId}
and u.school_id = #{schoolId}
group by id, labelName order by count desc

SELECT fl.id, fl.user_id userId, fl.label_name labelName, fl.label_type labelType, fl.color_value colorValue FROM t_wp_file_label fl left join t_base_user u on u.id = fl.user_id WHERE fl.is_valid = 1 and u.is_valid = 1
and fl.user_id = #{userId}
and u.school_id = #{schoolId}
